"""Root translation of current common weapon rules; legacy variants stay in the source archive."""
import json
from pathlib import Path
R=Path('.');a=json.loads((R/'inventory/critic-current-weapon-rules-source.json').read_text(encoding='utf8'))
ru={
'Accurate x':'Точное x (Accurate x): можно сохранить до x кубиков атаки как обычные успехи, не бросая их. Если оружие получает Accurate x несколько раз, можно считать это одним Accurate 2; это имеет приоритет над обычными правилами x.',
'Balanced':'Сбалансированное (Balanced): можно перебросить один свой кубик атаки.',
'Blast x':'Взрыв x (Blast x): выбранная цель — основная. После стрельбы по ней стреляйте этим оружием по каждой вторичной цели в выбранном порядке; каждую последовательность бросков разыгрывайте отдельно. Вторичные цели — другие оперативники, видимые основной цели и в пределах x от неё, например Blast 2″. Они считаются допустимыми целями независимо от приказа «Скрытность» (Conceal). Если основная цель находилась в укрытии (Cover) и/или была заслонена (Obscured), соответствующее состояние применяется и к вторичным целям.',
'Brutal':'Жестокое (Brutal): противник может блокировать (Block) только критическими успехами.',
'Ceaseless':'Непрерывное (Ceaseless): выберите одно значение результата; можно перебросить любые свои кубики атаки с этим результатом, например результаты 2.',
'Devastating x':'Опустошительное x (Devastating x): каждый сохранённый критический успех немедленно наносит x урона оперативнику, против которого используется оружие. Если правило начинается с дистанции, например 1″ Devastating x, нанесите x урона этому оперативнику и каждому другому оперативнику, видимому ему и в пределах указанной дистанции от него. Этот успех не сбрасывают: его можно применить позднее в последовательности.',
'Heavy':'Тяжёлое (Heavy): нельзя использовать это оружие в активацию или контрдействие, в которых оперативник перемещался; нельзя перемещаться в активацию или контрдействие, в которых он использовал это оружие. В записи Heavy (x only), где x — действие перемещения, разрешено только указанное перемещение, например Heavy (Dash only). Это правило не препятствует действию «Дозор» (Guard).',
'Hot':'Перегрев (Hot): после использования оружия бросьте D6. Если результат меньше HIT оружия, нанесите оперативнику урон, равный удвоенному результату. Даже если оружие применялось несколько раз в одном действии, например с Blast, бросьте только один D6.',
'Lethal x+':'Смертоносное x+ (Lethal x+): ваши успешные результаты x или выше считаются критическими успехами, например Lethal 5+.',
'Limited x':'Ограниченное x (Limited x): после x применений оружия за бой оперативник больше не имеет его. Несколько применений в одном действии, например с Blast, считаются одним применением.',
'Piercing x':'Бронебойное x (Piercing x): защищающийся берёт на x кубиков защиты меньше, например Piercing 1. В записи Piercing Crits x эффект действует только если вы сохранили хотя бы один критический успех.',
'Piercing Crits x':'Бронебойное при критических успехах x (Piercing Crits x): защищающийся берёт на x кубиков защиты меньше, только если вы сохранили хотя бы один критический успех.',
'Punishing':'Карающее (Punishing): если вы сохранили хотя бы один критический успех, можно сохранить один провал как обычный успех вместо его сброса.',
'Range x':'Дальность x (Range x): допустимыми целями (Valid Targets) могут быть только оперативники в пределах x от активного оперативника, например Range 9″.',
'Relentless':'Неумолимое (Relentless): можно перебросить любые свои кубики атаки.',
'Rending':'Рассечение (Rending): если вы сохранили хотя бы один критический успех, можно сохранить один свой обычный успех как критический.',
'Saturate':'Насыщение (Saturate): защищающийся не может сохранять защитные успехи за укрытие (Cover Saves).',
'Seek':'Обнаружение (Seek): при выборе допустимой цели оперативники не могут использовать террейн для укрытия (Cover). Seek Light действует только на лёгкий террейн (Light). Это может позволить выбрать видимого оперативника целью, но не отменяет его защитный успех за укрытие (Cover Save), если он есть.',
'Severe':'Сокрушительное (Severe): если вы не сохранили ни одного критического успеха, можно изменить один обычный успех на критический. Devastating и Piercing Crits при этом действуют, а Punishing и Rending — нет.',
'Shock':'Потрясение (Shock): при первом ударе (Strike) критическим успехом в каждой последовательности также сбросьте один ещё не применённый обычный успех противника; если обычных нет — один критический.',
'Silent':'Бесшумное (Silent): оперативник может выполнять «Стрельбу» (Shoot) этим оружием с приказом «Скрытность» (Conceal).',
'Stun':'Оглушение (Stun): если вы сохранили хотя бы один критический успех, уменьшите APL оперативника, против которого используется оружие, на 1 до конца его следующей активации.',
'Torrent x':'Поток x (Torrent x): выберите допустимую основную цель по обычным правилам. Затем выберите любое число других допустимых вторичных целей в пределах x от первой, но вне дистанции контроля дружественных оперативников, например Torrent 2″. Стреляйте этим оружием по всем выбранным целям в выбранном порядке; каждую последовательность бросков разыгрывайте отдельно.'}
out={}
for x in a['genericWeaponRules']:
 key=x['rule'];assert key in ru,key;out[key.removesuffix(' x+').removesuffix(' x')]={'russian':ru[key],'english':x['englishBody'],'source':x['source']}
out['Seek Light']=out['Seek'];out['PSYCHIC']={'russian':'ПСИХИЧЕСКОЕ (PSYCHIC): метка психического оружия или действия. Дополнительные взаимодействия указаны в правилах соответствующего отряда.'}
(R/'ru-current-weapon-rules.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(len(out))
